// One item per copy, tagged with what has to happen to it and which
// account carries it. A copy belongs to a page or a shop, not to a
// platform in the abstract: a business with two Facebook pages has two
// copies out there with two ids, and each is edited with that page's own
// token — which is why the account id travels with the item from here.
//
// An external id means the platform already holds a copy, so this is an
// edit; no id means it has never gone out, so this is a first publish.
const body = $input.first().json.body;
const post = body.post;
// The approval names the copies it is for. Older ones named platforms,
// which is the same thing while a business has one account per platform.
const wantedAccounts = (body.payload.targets ?? []).map((t) => t.account_id);
const wantedPlatforms = body.payload.platforms ?? [];

return post.targets
  .filter((t) => (wantedAccounts.length
    ? wantedAccounts.includes(t.account_id)
    : wantedPlatforms.includes(t.platform)))
  .map((t) => ({ json: {
    post_id: post.id,
    account_id: t.account_id,
    account_label: t.label ?? null,
    platform: t.platform,
    external_id: t.external_id ?? null,
    action: t.external_id ? 'update' : 'publish',
    body: body.payload.draft,
    title: post.title,
    media_url: post.media_url ?? null,
  } }));

// Instagram does not let the Graph API edit a published caption. The honest
// thing is to report it rather than pretend the platform was updated: the
// dashboard then shows that copy as failed, with this reason on it.
return $input.all().map((item) => ({ json: {
  ...item.json,
  state: 'FAILED',
  error: 'Instagram captions cannot be edited through the API — update this one in the app, or delete and repost.',
} }));

// Normalise the platform's answer into the one shape Report Back expects.
return $input.all().map((item) => {
  const res = item.json;
  const sent = res.skip === true ? null : res;
  if (res.skip === true) return { json: res };
  const ok = res.statusCode >= 200 && res.statusCode < 300
    && !(res.body && res.body.error && res.body.error !== 'ok' && res.body.error !== '');
  return { json: {
    post_id: res.post_id,
    platform: 'facebook',
    external_id: res.body?.id ?? res.external_id,
    state: ok ? 'PUBLISHED' : 'FAILED',
    error: ok ? null : ('facebook refused it: ' + JSON.stringify(res.body ?? {}).slice(0, 240)),
  } };
});

// Shopee signs every call. The base string for a shop-level API is
//   partner_id + api_path + timestamp + access_token + shop_id
// hashed with HMAC-SHA256 under the partner key, hex, lower case.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto, which docker-compose.yml sets.
//
// The keys belong to the shop this copy is on, not to the deployment.
// Read from $env they were the same for every business on it, so one
// seller's post went out of another seller's shop.
const crypto = require('crypto');

const creds = $('Account Credentials').item.json.credentials ?? {};
const shop = $('One Item Per Account').item.json.account_label || 'this shop';
const partnerId = Number(creds.partner_id);
const partnerKey = creds.partner_key;
const shopId = Number(creds.shop_id);
const accessToken = creds.access_token;
const host = creds.host || $env.SHOPEE_HOST || 'https://partner.shopeemobile.com';

return $input.all().map((item) => {
  const missing = [];
  if (!partnerId) missing.push('partner_id');
  if (!partnerKey) missing.push('partner_key');
  if (!shopId) missing.push('shop_id');
  if (!accessToken) missing.push('access_token');
  if (missing.length) {
    return { json: { ...item.json, skip: true, state: 'FAILED',
      error: `Shopee ${missing.join(', ')} ${missing.length > 1 ? 'are' : 'is'}`
        + ` not set for ${shop} — reconnect it.` } };
  }

  // Shopee has no "create a listing from a caption" call — a new item needs a
  // category, attributes and logistics. Editing an existing one is the part
  // that maps onto a post, so a first publish is reported rather than faked.
  if (item.json.action === 'publish') {
    return { json: { ...item.json, skip: true, state: 'FAILED',
      error: 'Shopee listings are created in Seller Centre; this app can edit one once it exists.' } };
  }

  const path = '/api/v2/product/update_item';
  const timestamp = Math.floor(Date.now() / 1000);
  const base = `${partnerId}${path}${timestamp}${accessToken}${shopId}`;
  const sign = crypto.createHmac('sha256', partnerKey).update(base).digest('hex');

  return { json: { ...item.json, skip: false,
    url: `${host}${path}?partner_id=${partnerId}&timestamp=${timestamp}`
       + `&access_token=${accessToken}&shop_id=${shopId}&sign=${sign}`,
    payload: { item_id: Number(item.json.external_id), description: item.json.body },
  } };
});

// Normalise the platform's answer into the one shape Report Back expects.
return $input.all().map((item) => {
  const res = item.json;
  const sent = res.skip === true ? null : res;
  if (res.skip === true) return { json: res };
  const ok = res.statusCode >= 200 && res.statusCode < 300
    && !(res.body && res.body.error && res.body.error !== 'ok' && res.body.error !== '');
  return { json: {
    post_id: res.post_id,
    platform: 'shopee',
    external_id: res.external_id,
    state: ok ? 'PUBLISHED' : 'FAILED',
    error: ok ? null : ('shopee refused it: ' + JSON.stringify(res.body ?? {}).slice(0, 240)),
  } };
});

// TikTok's Content Posting API can put a post up, but there is no endpoint to
// change one after it is live — so an edit is reported honestly instead of
// being silently dropped.
// The token belongs to the account this copy is on, not to the deployment.
const creds = $('Account Credentials').item.json.credentials ?? {};
const shop = $('One Item Per Account').item.json.account_label || 'this account';

return $input.all().map((item) => {
  if (!creds.access_token) {
    return { json: { ...item.json, skip: true, state: 'FAILED',
      error: `TikTok access_token is not set for ${shop} — reconnect it.` } };
  }
  if (item.json.action === 'update') {
    return { json: { ...item.json, skip: true, state: 'FAILED',
      error: 'TikTok posts cannot be edited after publishing — delete and repost, or edit in the app only.' } };
  }
  if (!item.json.media_url) {
    return { json: { ...item.json, skip: true, state: 'FAILED',
      error: 'TikTok needs an image or video; this post has no media.' } };
  }
  const isVideo = /\.(mp4|mov|webm)(\?|$)/i.test(item.json.media_url);
  return { json: { ...item.json, skip: false, access_token: creds.access_token,
    url: 'https://open.tiktokapis.com/v2/post/publish/'
       + (isVideo ? 'video' : 'content') + '/init/',
    payload: {
      post_info: {
        title: item.json.title.slice(0, 90),
        description: item.json.body.slice(0, 4000),
        privacy_level: $env.TIKTOK_PRIVACY_LEVEL || 'PUBLIC_TO_EVERYONE',
      },
      source_info: isVideo
        ? { source: 'PULL_FROM_URL', video_url: item.json.media_url }
        : { source: 'PULL_FROM_URL', photo_cover_index: 0, photo_images: [item.json.media_url] },
      post_mode: 'DIRECT_POST',
      media_type: isVideo ? 'VIDEO' : 'PHOTO',
    },
  } };
});

// Normalise the platform's answer into the one shape Report Back expects.
return $input.all().map((item) => {
  const res = item.json;
  const sent = res.skip === true ? null : res;
  if (res.skip === true) return { json: res };
  const ok = res.statusCode >= 200 && res.statusCode < 300
    && !(res.body && res.body.error && res.body.error !== 'ok' && res.body.error !== '');
  return { json: {
    post_id: res.post_id,
    platform: 'tiktok',
    external_id: res.body?.data?.publish_id ?? null,
    state: ok ? 'PUBLISHED' : 'FAILED',
    error: ok ? null : ('tiktok refused it: ' + JSON.stringify(res.body ?? {}).slice(0, 240)),
  } };
});

return $input.all().map((item) => ({ json: {
  ...item.json,
  state: 'FAILED',
  error: item.json.error ?? ('No sender is wired up for ' + item.json.platform + ' yet.'),
} }));
